using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_external_data"), Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchExternalDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTool> logger,
        [Description("The URL to fetch data from")] string url,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching data from {Url}", url);

        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);

        logger.LogInformation("Successfully fetched {Length} characters", content.Length);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt to summarize the given text.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired style: brief, detailed, or bullet-points")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "detailed" => "Provide a comprehensive summary covering all key points.",
            "bullet-points" => "Summarize the text as a concise bullet-point list.",
            _ => "Provide a brief one-paragraph summary."
        };

        return
        [
            new(Microsoft.Extensions.AI.ChatRole.System, systemInstruction),
            new(Microsoft.Extensions.AI.ChatRole.User, $"Please summarize the following text:\n\n{text}")
        ];
    }
}

